class Solution { public: int minimumOperations(vector<int>& nums,int start,int goal){if(start==goal)return 0;vector<bool> visited(1001);queue<int> pending;pending.push(start);visited[start]=true;int steps=0;while(!pending.empty()){int size=pending.size();while(size--){int value=pending.front();pending.pop();for(int num:nums)for(int next:{value+num,value-num,value^num}){if(next==goal)return steps+1;if(next>=0&&next<=1000&&!visited[next]){visited[next]=true;pending.push(next);}}}++steps;}return -1;} };
